    /**
     * The password visibility toggle of a {@link TextInputLayout} only affects the {@link EditText}
     * it contains. This links an additional (confirmation) field to that toggle, so that the
     * visibility of both fields is changed at the same time.
     *
     * The default toggle behaviour is replaced, but the state of the toggle icon itself is still
     * updated by the {@link TextInputLayout}, since it tracks the transformation method of its own
     * {@link EditText}.
     *
     * @param passwordLayout  the layout providing the password visibility toggle
     * @param passwordConfirm the additional field that should follow the toggle
     */
    public static void linkPasswordConfirmToToggle(final TextInputLayout passwordLayout, final EditText passwordConfirm) {
        if (passwordLayout == null)
            return;

        passwordLayout.setEndIconOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View view) {
                EditText passwordInput = passwordLayout.getEditText();

                if (passwordInput == null)
                    return;

                boolean showPassword = isPasswordHidden(passwordInput);

                setPasswordVisibility(passwordInput, showPassword);
                setPasswordVisibility(passwordConfirm, showPassword);
            }
        });
    }

    private static boolean isPasswordHidden(EditText editText) {
        return editText.getTransformationMethod() instanceof PasswordTransformationMethod;
    }

    private static void setPasswordVisibility(EditText editText, boolean visible) {
        if (editText == null || isPasswordHidden(editText) != visible)
            return;

        // Changing the transformation method can reset the cursor position, so restore it
        int selection = editText.getSelectionEnd();

        editText.setTransformationMethod(visible ? null : new PasswordTransformationMethod());

        if (selection >= 0)
            editText.setSelection(selection);
    }
}

